const langMap = {
  'Deutsch (de)': 'de',
  'Englisch (en)': 'en',
  'Automatisch erkennen (auto)': 'auto'
};
const language = langMap[$json['Sprache']] || 'auto';
const numSpeakers = parseInt($json['Anzahl Sprecher']) || 2;
const title = ($json['Titel des Interviews'] || '').trim();

const namesRaw = $json['Namen der Sprecher, kommagetrennt, in der Reihenfolge des ersten Sprechens'] || '';
const speakerNames = namesRaw
  .split(',')
  .map(n => n.trim())
  .filter(n => n.length > 0);

const includeVtt = Array.isArray($json['VTT Timestamps'])
  ? $json['VTT Timestamps'].length > 0
  : false;

const replaceUmlauts = (s) =>
  (s || '').replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue')
           .replace(/Ä/g,'Ae').replace(/Ö/g,'Oe').replace(/Ü/g,'Ue')
           .replace(/ß/g,'ss').normalize('NFD').replace(/[\u0300-\u036f]/g,'');

const directory = replaceUmlauts($json['Zielverzeichnis'] || 'transkripte')
  .replace(/[^a-zA-Z0-9\/_-]/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .toLowerCase();

const bucket = $json['Ziel-Bucket'] || 'audio-transcripts';
const email = $json['E-Mail'];

const binaryKey = Object.keys($binary || {})[0] || 'Audiodatei';
const fileName = $binary?.[binaryKey]?.fileName || 'audio.mp3';
const baseName = replaceUmlauts(fileName.replace(/\.[^.]+$/, ''))
  .replace(/[^a-zA-Z0-9_-]/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-+|-+$/g, '');

return [{
  json: { language, minSpeakers: numSpeakers, maxSpeakers: numSpeakers, speakerNames, title, directory, bucket, email, fileName, baseName, binaryKey, includeVtt },
  binary: $binary
}];

const result = $json;
const meta = $('Prepare Request').first().json;

if (result.status !== 'success') {
  throw new Error('WhisperX Fehler: ' + JSON.stringify(result));
}

const segments = result.segments || [];
const language = result.language || meta.language;
const speakerNames = meta.speakerNames || [];
const title = meta.title || meta.fileName;
const includeVtt = meta.includeVtt === true;

// HH:MM:SS für Markdown
const fmt = (s) => {
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = Math.floor(s % 60);
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;
};

// MM:SS.mmm für VTT
const fmtVtt = (s) => {
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = Math.floor(s % 60);
  const ms = Math.round((s % 1) * 1000);
  if (h > 0) {
    return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${String(ms).padStart(3,'0')}`;
  }
  return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${String(ms).padStart(3,'0')}`;
};

// Sprecher mappen
const speakerMap = {};
let speakerCounter = 1;
for (const seg of segments) {
  const raw = seg.speaker;
  if (raw && !(raw in speakerMap)) {
    speakerMap[raw] = speakerNames[speakerCounter - 1] || `Sprecher ${speakerCounter}`;
    speakerCounter++;
  }
}

// Segmente zu Sprecherblöcken zusammenfassen
const blocks = [];
let currentBlock = null;
for (const seg of segments) {
  const raw = seg.speaker || 'UNBEKANNT';
  const speaker = speakerMap[raw] || raw;
  const text = (seg.text || '').trim();
  if (!text) continue;
  if (!currentBlock || currentBlock.speaker !== speaker) {
    if (currentBlock) blocks.push(currentBlock);
    currentBlock = { speaker, ts_start: seg.start || 0, ts_end: seg.end || 0, lines: [text] };
  } else {
    currentBlock.ts_end = seg.end || currentBlock.ts_end;
    currentBlock.lines.push(text);
  }
}
if (currentBlock) blocks.push(currentBlock);

// Markdown bauen
let md = `# ${title}\n\n`;
for (const block of blocks) {
  md += `### ${block.speaker}\n`;
  md += block.lines.join('  \n') + '  \n';
  md += '\n';
}

// VTT bauen
let vtt = 'WEBVTT\n\n';
for (const block of blocks) {
  vtt += `${fmtVtt(block.ts_start)} --> ${fmtVtt(block.ts_end)}\n`;
  vtt += `[${block.speaker}] ${block.lines.join(' ')}\n\n`;
}

const speakers = [...new Set(segments.map(s => s.speaker))].filter(Boolean);
const speakerList = Object.values(speakerMap).join(', ');

return [{
  json: {
    content: md,
    vttContent: includeVtt ? vtt : null,
    includeVtt,
    directory: meta.directory,
    bucket: meta.bucket,
    baseName: meta.baseName,
    email: meta.email,
    fileName: meta.fileName,
    title,
    language,
    speakerCount: speakers.length,
    speakerList
  }
}];

const data = $('Format Markdown').first().json;
const now = new Date().toISOString().split('T')[0];

const attachments = {
  attachment: {
    data: Buffer.from(data.content, 'utf8').toString('base64'),
    mimeType: 'text/plain',
    fileName: data.baseName + '_' + now + '.md',
    fileExtension: 'md'
  }
};

if (data.includeVtt && data.vttContent) {
  attachments.attachmentVtt = {
    data: Buffer.from(data.vttContent, 'utf8').toString('base64'),
    mimeType: 'text/vtt',
    fileName: data.baseName + '_' + now + '.vtt',
    fileExtension: 'vtt'
  };
}

return [{
  json: data,
  binary: attachments
}];
